// suiko-debug.js — debug.html only. Boots straight into the scenario-warp menu that Compile
// left in the retail KR build but wired to nothing: 시나리오１～９ + 데모 + 미니게임 + 기타,
// with 시나리오９ labelled （체험판）. Backing out of it lands on the untouched title screen,
// where 처음부터/이어서하기 work normally. See NOTES.md 3.4.
//
// Patching happens on the in-memory disk image right before Module.callMain(), the same way
// suiko-lang.js rewrites WIN.INI — so kr.html/jp.html and the shipped final-shared.img stay
// untouched and no second ~35MB image is needed. The byte patch itself is data, generated by
// `node kr-patch/tools/debug-menu.js --emit-patch docs/debug-patch.json` (one byte, for the
// default --mode direct), so the PE-level reasoning lives in one place instead of being
// reimplemented here. This file just validates and applies whatever runs that file lists.
(function () {
  'use strict';
  var PATCH_URL = 'debug-patch.json';

  function b64ToBytes(s) {
    var bin = atob(s);
    var out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  function readU32(bytes, off) {
    return (bytes[off] | (bytes[off + 1] << 8) | (bytes[off + 2] << 16) | (bytes[off + 3] << 24)) >>> 0;
  }

  function patchDebugMenu(baseName) {
    // The patched menu is KR-only: the offsets are HWANSE.EXE's, and JP's GENSE.EXE lays the
    // same script data out differently (its menu strings sit ~400KB earlier).
    if (window.SUIKO_LANG !== 'kr') {
      console.warn('[suiko-debug] KR 전용 패치 — SUIKO_LANG=' + window.SUIKO_LANG + ', 건너뜀');
      return Promise.resolve();
    }
    return fetch(PATCH_URL)
      .then(function (r) {
        if (!r.ok) throw new Error(PATCH_URL + ' ' + r.status);
        return r.json();
      })
      .then(function (patch) {
        var path = '/' + baseName + '.img';
        var img = Module.FS.readFile(path);
        var ctx = Fat16.openImage(img);
        var dir = Fat16.resolveDir(ctx, patch.dir);
        var entry = Fat16.listDir(ctx, dir).find(function (e) {
          return e.shortName.toUpperCase() === patch.target;
        });
        if (!entry) throw new Error(patch.dir + '\\' + patch.target + ' not found in the image');

        // Copy: readFileEntry may hand back a view onto the image buffer.
        var exe = new Uint8Array(Fat16.readFileEntry(ctx, entry));
        if (exe.length !== patch.size) {
          throw new Error('size mismatch: image has ' + exe.length + ', patch expects ' + patch.size);
        }
        // Refuse to write into an EXE this patch was not generated against — a stale
        // debug-patch.json would otherwise scribble over whatever now lives at those offsets.
        patch.expect.forEach(function (e) {
          var got = readU32(exe, e.offset);
          if (got !== e.u32 >>> 0) {
            throw new Error(
              'unexpected bytes at ' + e.offset + ': got 0x' + got.toString(16) +
                ', expected 0x' + (e.u32 >>> 0).toString(16) + ' — regenerate debug-patch.json'
            );
          }
        });

        patch.writes.forEach(function (w) {
          exe.set(b64ToBytes(w.bytes), w.offset);
        });

        var res = Fat16.injectDirFiles(img, patch.dir, [{ name: patch.target, data: exe }]);
        if (res.skipped.length) throw new Error('inject skipped: ' + res.skipped.join(','));
        Module.FS.writeFile(path, res.image);
        console.log('[suiko-debug] patched (' + patch.mode + ', ' + patch.writes.length + ' runs)');
        if (window.showToast) window.showToast('디버그 빌드: 시나리오 선택으로 시작합니다.');
      })
      .catch(function (e) {
        console.warn('[suiko-debug] 패치 실패, 원본으로 부팅합니다:', e);
        if (window.showToast) window.showToast('디버그 메뉴 패치 실패 — 원본으로 실행');
      });
  }

  window.SuikoDebug = { patchDebugMenu: patchDebugMenu };
})();
